import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';

const Header = () => {
  const [navOpen, setNavOpen] = useState(false);
  const location = useLocation();
  const { user } = useAuth();

  const toggleNav = () => {
    setNavOpen(!navOpen);
  };

  const closeNav = () => {
    setNavOpen(false);
  };

  const handleLogoClick = (e) => {
    e.preventDefault();
    // Handle logo click - could show admin login or just navigate home
    window.location.href = '/';
  };

  return (
    <>
      <nav id="nav">
        <Link className="nlogo" to="/" onClick={handleLogoClick} id="logoBtn">
          <div className="nmk">CX</div>Clarix
        </Link>
        <ul className="nl" id="nl">
          <li><Link to="/" className={location.pathname === '/' ? 'act' : ''} id="n-home">Home</Link></li>
          <li><Link to="/services" className={location.pathname === '/services' ? 'act' : ''} id="n-services">Services</Link></li>
          <li><Link to="/works" className={location.pathname === '/works' ? 'act' : ''} id="n-works">How It Works</Link></li>
          <li><Link to="/tools" className={location.pathname === '/tools' ? 'act' : ''} id="n-tools">AI Tools</Link></li>
          <li><Link to="/about" className={location.pathname === '/about' ? 'act' : ''} id="n-about">About</Link></li>
          <li><Link to="/cases" className={location.pathname === '/cases' ? 'act' : ''} id="n-cases">Cases</Link></li>
          <li><Link to="/blog" className={location.pathname === '/blog' ? 'act' : ''} id="n-blog">Blog</Link></li>
          <li><Link to="/testimonials" className={location.pathname === '/testimonials' ? 'act' : ''} id="n-testimonials">Testimonials</Link></li>
          <li><Link to="/pricing" className={location.pathname === '/pricing' ? 'act' : ''} id="n-pricing">Pricing</Link></li>
          <li><Link to="/resources" className={location.pathname === '/resources' ? 'act' : ''} id="n-resources">Resources</Link></li>
          {user && <li><Link to="/admin" className={location.pathname === '/admin' ? 'act' : ''} id="n-admin">Admin</Link></li>}
        </ul>
        <Link className="ncta" to="/contact">Start a Project</Link>
        <button className="ntog" onClick={toggleNav}>
          <span></span><span></span>
        </button>
      </nav>

      <div className={`pg ${navOpen ? 'on' : ''}`} id="mobile-nav">
        <div style={{ padding: '100px 2rem 2rem' }}>
          <ul style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <li><Link to="/" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>Home</Link></li>
            <li><Link to="/services" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>Services</Link></li>
            <li><Link to="/works" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>How It Works</Link></li>
            <li><Link to="/tools" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>AI Tools</Link></li>
            <li><Link to="/about" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>About</Link></li>
            <li><Link to="/cases" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>Cases</Link></li>
            <li><Link to="/blog" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>Blog</Link></li>
            <li><Link to="/testimonials" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>Testimonials</Link></li>
            <li><Link to="/pricing" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>Pricing</Link></li>
            <li><Link to="/resources" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>Resources</Link></li>
            {user && <li><Link to="/admin" onClick={closeNav} style={{ color: '#f5f5f7', textDecoration: 'none', fontSize: '1.1rem' }}>Admin</Link></li>}
            <li style={{ marginTop: '1rem' }}>
              <Link to="/contact" onClick={closeNav} style={{
                background: '#b8935a',
                color: '#1d1d1f',
                padding: '0.75rem 1.5rem',
                borderRadius: '20px',
                textDecoration: 'none',
                fontWeight: '600',
                display: 'inline-block'
              }}>
                Start a Project
              </Link>
            </li>
          </ul>
        </div>
      </div>
    </>
  );
};

export default Header;
